function exportData(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`china-ledger-${today()}${demo?'-demo':''}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setToast('Резервная копия скачана')}
async function importData(file:File){try{if(file.size>3000000)throw Error('Файл слишком большой');const data=JSON.parse(await file.text());const parsed=stateSchema.parse(data.state||data);if(!confirm('Заменить все текущие записи данными из этого файла? Сначала скачайте резервную копию, если хотите сохранить текущие записи.'))return;if(await save(parsed))setToast(demo?'Пример обновлён':'Записи восстановлены')}catch{setToast('Файл не подходит. Выберите резервную копию этого приложения.')}}
async function removeShipment(id:string){if(saving)return;if(demo){if(state.transactions.some(t=>t.shipmentId===id)){setFormError('Сначала удалите или перенесите операции этого груза.');return}if(await save({...state,shipments:state.shipments.filter(s=>s.id!==id)}))setModal(null);return}setSaving(true);setFormError('');try{const r=await fetch('/api/shipments/'+id,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision})}),j=await r.json() as {error?:string;state:Ledger;revision:number};if(!r.ok)throw Error(j.error||'Не удалось удалить груз');setReal(withWallets(withSuppliers(stateSchema.parse(j.state))));setRevision(j.revision);setModal(null);setToast('Груз удалён')}catch(e){setFormError(e instanceof Error?e.message:'Не удалось удалить груз')}finally{setSaving(false)}}

