{(tab==='overview'||tab==='shipments')&&<section><div className="section-heading"><h2>{tab==='overview'?'Последние грузы':'Все грузы'} <span>{tab==='shipments'&&hasShipmentFilters?`${filtered.length} из ${state.shipments.length}`:state.shipments.length}</span></h2><button className="btn outline" disabled={!!error||saving} onClick={()=>open('shipment')}><Plus size={17}/> Новый груз</button></div>{tab==='shipments'&&<div className="filters"><label className="search"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Название, поставщик, номер груза"/></label><select aria-label="Статус груза" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="all">Все статусы</option>{Object.entries(statusNames).map(([v,n])=><option key={v} value={v}>{n}</option>)}</select></div>}{tab==='shipments'&&<ShipmentFilters value={shipmentFilters} onChange={setShipmentFilters} suppliers={state.suppliers||[]} shipments={state.shipments} active={hasShipmentFilters} onReset={()=>{setShipmentFilters(emptyShipmentFilters);setQuery('');setStatusFilter('all')}}/>}{filtered.length?<div className="shipment-grid">{(tab==='overview'?[...filtered].reverse().slice(0,4):[...filtered].reverse()).map(card)}</div>:<div className="empty-state"><Package size={36}/><h3>{hasShipmentFilters?'Грузы не найдены':'Добавьте первую закупку'}</h3><p>{hasShipmentFilters?'Измените период, поставщика или другие фильтры.':'Укажите товар, поставщика и сумму заказа. Затем привязывайте к нему оплаты и доставку.'}</p>{!hasShipmentFilters&&<button className="btn primary" disabled={!!error} onClick={()=>open('shipment')}><Plus size={17}/> Создать груз</button>}</div>}</section>}
